// Lesson 03b: display showcase, on the same display wiring as lesson 03.
//
// Four scenes, each pushing the screen a different way:
//   1. 3D torus    rotation, projection, lighting, depth sorting
//   2. Plasma      every pixel computed from sine waves, every frame
//   3. Fireworks   a particle system with gravity and fading trails
//   4. Dashboard   live chip temperature, memory use and frame timing
//
// Two variations, same scenes (pick one with the PlatformIO environment):
//   03b-showcase          variation 1: BOOT button. click = next, long press = auto-cycle
//   03b-showcase-button   variation 2: push button on GPIO 5 (+ BOOT). click = next,
//                         double-click = previous, long press = auto-cycle
// Serial monitor, both variations: next | prev | scene <1-4> | auto on|off | hud | help
//
// New ideas in this lesson:
//   - Our own frame buffer in fast internal RAM (see frame_buffer.h)
//   - Splitting a program into small parts with one shared contract (scene.h)
//   - Measuring: we time drawing and sending separately, so we know what is slow
//   - Variation 2: interrupts and debouncing for buttons (see button.h)
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <Arduino.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <SPI.h>
#include <esp_heap_caps.h>

#include "color.h"
#include "controls.h"
#include "frame_buffer.h"
#include "pins.h"
#include "scenes/dashboard.h"
#include "scenes/fireworks.h"
#include "scenes/plasma.h"
#include "scenes/torus.h"
#include "stats.h"

namespace {

constexpr int16_t kW = 320, kH = 170;
constexpr uint32_t kSpiHz = 40'000'000;
constexpr uint32_t kAutoCycleMs = 12'000;  // time per scene when auto-cycling
constexpr uint32_t kBannerMs = 2'000;      // how long the scene title stays up

Adafruit_ST7789 tft(&SPI, PIN_TFT_CS, PIN_TFT_DC, PIN_TFT_RST);
FrameBuffer fb(kW, kH);
Stats stats;

TorusScene torus;
PlasmaScene plasma;
FireworksScene fireworks;
DashboardScene dashboard(stats);
Scene *const scenes[] = {&torus, &plasma, &fireworks, &dashboard};
constexpr int kSceneCount = sizeof(scenes) / sizeof(scenes[0]);

struct {
  int scene = 0;
  uint32_t sceneStartedAt = 0;
  bool autoCycle = true;
  bool hud = true;
} state;

// ---- Scene switching ------------------------------------------------------------------------

void showScene(int index) {
  state.scene = (index % kSceneCount + kSceneCount) % kSceneCount;
  state.sceneStartedAt = millis();
  scenes[state.scene]->enter(fb);
  log_i("scene %d/%d: %s", state.scene + 1, kSceneCount, scenes[state.scene]->name());
}

// ---- Overlays drawn on top of every scene ---------------------------------------------------

// The scene title slides down from the top, waits, and slides back up.
void drawBanner(uint32_t sinceStart) {
  if (sinceStart >= kBannerMs) return;
  constexpr uint32_t slide = 250;
  float k = 1;
  if (sinceStart < slide) k = sinceStart / float(slide);
  else if (sinceStart > kBannerMs - slide) k = (kBannerMs - sinceStart) / float(slide);
  k = 1 - (1 - k) * (1 - k);  // ease out

  char text[40];
  snprintf(text, sizeof(text), "%d/%d  %s", state.scene + 1, kSceneCount, scenes[state.scene]->name());
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextSize(1);
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(text, 0, 0, &x1, &y1, &w, &h);
  const int bw = w + 28, bh = 28, bx = (kW - bw) / 2, by = int(-bh + (bh + 8) * k);
  fb.fillRoundRect(bx, by, bw, bh, 14, pal::ink);
  fb.setTextColor(pal::night);
  fb.setCursor(bx + 14 - x1, by + 19);
  fb.print(text);
}

// Frame timing in the bottom-left corner: the numbers we will improve in the speed lesson.
void drawHud() {
  if (!state.hud) return;
  char text[48];
  snprintf(text, sizeof(text), "%2.0f fps  draw %4.1f  send %4.1f ms%s", stats.fps, stats.drawMs, stats.pushMs,
           state.autoCycle ? "  auto" : "");
  fb.setFont(nullptr);
  fb.setTextSize(1);
  fb.fillRect(0, kH - 12, int(strlen(text)) * 6 + 8, 12, pal::night);
  fb.setTextColor(pal::amber);
  fb.setCursor(4, kH - 10);
  fb.print(text);
}

// Variation 2 only: a dot in the bottom-right corner that lights while a button is held down.
void drawButtonDot() {
  if (!controls::showsPressDot()) return;
  fb.fillCircle(kW - 10, kH - 10, 5, controls::anyDown() ? pal::teal : pal::dim);
  fb.drawCircle(kW - 10, kH - 10, 6, pal::night);
}

// ---- Input -----------------------------------------------------------------------------------

void printHelp() {
  Serial.println();
  Serial.println("Commands: next | prev | scene <1-4> | auto on|off | hud | help");
  Serial.println(controls::help());
}

void handleCommand(String line) {
  line.trim();
  line.toLowerCase();
  if (line.isEmpty()) return;
  if (line == "next") return showScene(state.scene + 1);
  if (line == "prev") return showScene(state.scene - 1);
  if (line == "hud") {
    state.hud = !state.hud;
    log_i("hud %s", state.hud ? "on" : "off");
    return;
  }
  if (line == "auto on" || line == "auto off") {
    state.autoCycle = line == "auto on";
    log_i("auto-cycle %s", state.autoCycle ? "on" : "off");
    return;
  }
  if (line.startsWith("scene ")) {
    const long n = line.substring(6).toInt();
    if (n < 1 || n > kSceneCount) {
      log_w("scene needs a number 1-%d, got '%s'", kSceneCount, line.substring(6).c_str());
      return;
    }
    return showScene(n - 1);
  }
  if (line == "help" || line == "?") return printHelp();
  log_w("unknown command '%s' (type help)", line.c_str());
}

void pollSerial() {
  static String buffer;
  while (Serial.available()) {
    const char c = Serial.read();
    if (c == '\n' || c == '\r') {
      handleCommand(buffer);
      buffer = "";
    } else if (buffer.length() < 32) {
      buffer += c;
    }
  }
}

void pollControls() {
  switch (controls::poll()) {
    case Action::NextScene:
      showScene(state.scene + 1);
      break;
    case Action::PreviousScene:
      showScene(state.scene - 1);
      break;
    case Action::ToggleAutoCycle:
      state.autoCycle = !state.autoCycle;
      log_i("auto-cycle %s", state.autoCycle ? "on" : "off");
      break;
    case Action::None:
      break;
  }
}

}  // namespace

void setup() {
  Serial.begin(115200);
  delay(1500);

  pinMode(PIN_TFT_BL, OUTPUT);
  digitalWrite(PIN_TFT_BL, HIGH);
  SPI.begin(PIN_TFT_SCLK, -1, PIN_TFT_MOSI, PIN_TFT_CS);
  tft.init(170, 320);
  tft.setSPISpeed(kSpiHz);
  tft.setRotation(1);
  tft.fillScreen(pal::night);

  const size_t largest = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL);
  if (!fb.begin()) {
    log_e("No memory for the %u-byte frame buffer, internal or PSRAM. Stopping.", unsigned(fb.bytesUsed()));
    return;
  }
  log_i("Frame buffer: %u KB in %s (largest free internal block was %u KB)", unsigned(fb.bytesUsed() / 1024),
        fb.internal() ? "internal RAM (fast)" : "PSRAM (slower)", unsigned(largest / 1024));

  controls::begin();
  randomSeed(esp_random());
  printHelp();
  showScene(0);
}

void loop() {
  if (fb.pixels() == nullptr) {
    delay(1000);
    return;
  }
  pollSerial();
  pollControls();

  static uint32_t lastFrame = millis(), lastLog = 0, lastTemp = 0;
  const uint32_t now = millis();
  const float dt = (now - lastFrame) / 1000.0f;
  lastFrame = now;

  if (state.autoCycle && now - state.sceneStartedAt >= kAutoCycleMs) showScene(state.scene + 1);
  if (now - lastTemp >= 1000) {  // the temperature changes slowly; once a second is plenty
    lastTemp = now;
    stats.tempC = temperatureRead();
  }

  // Draw the whole picture in memory, then send it in one go. Time both halves.
  const uint32_t t0 = micros();
  scenes[state.scene]->render(fb, (now - state.sceneStartedAt) / 1000.0f, dt);
  drawBanner(now - state.sceneStartedAt);
  drawHud();
  drawButtonDot();
  const uint32_t t1 = micros();
  tft.drawRGBBitmap(0, 0, fb.pixels(), kW, kH);
  const uint32_t t2 = micros();
  stats.add((t1 - t0) / 1000.0f, (t2 - t1) / 1000.0f, dt);

  if (now - lastLog >= 5000) {
    lastLog = now;
    log_i("%-14s %5.1f fps | draw %5.1f ms | send %5.1f ms | %.1f C", scenes[state.scene]->name(), stats.fps,
          stats.drawMs, stats.pushMs, stats.tempC);
  }
}

// How the showcase is controlled, without main.cpp knowing which buttons exist.
//
// Two variations implement this, and platformio.ini compiles exactly one of them:
//   controls/boot_only.cpp     variation 1, env 03b-showcase: the BOOT button, nothing to wire
//   controls/with_button.cpp   variation 2, env 03b-showcase-button: a push button on GPIO 5 + BOOT
#pragma once

// What a button gesture asks the showcase to do.
enum class Action { None, NextScene, PreviousScene, ToggleAutoCycle };

namespace controls {

void begin();
// Call every loop. Returns at most one action per call.
Action poll();
// True while a button is held down (variation 2 lights a dot on screen).
bool anyDown();
// Whether this variation draws the press dot.
bool showsPressDot();
// One line for the serial help text.
const char *help();

}  // namespace controls

// Scene 4: a live dashboard with real numbers from your chip.
//   - an arc gauge for the chip's internal temperature sensor
//   - bars for how much internal RAM and PSRAM are in use
//   - a chart of how long the last 120 frames took to draw and send
#pragma once

#include <Arduino.h>
#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold12pt7b.h>
#include <esp_heap_caps.h>
#include <math.h>

#include <algorithm>

#include "color.h"
#include "../scene.h"
#include "../stats.h"

class DashboardScene : public Scene {
 public:
  explicit DashboardScene(const Stats &stats) : stats_(stats) {}

  const char *name() const override { return "Live dashboard"; }

  void render(FrameBuffer &fb, float t, float) override {
    fb.fillScreen(pal::night);
    drawTemperature(fb, t);
    drawMemory(fb);
    drawFrameChart(fb);
  }

 private:
  // ---- Arc gauge -------------------------------------------------------------------------
  void drawTemperature(FrameBuffer &fb, float t) {
    constexpr int cx = 72, cy = 96, rOut = 54, rIn = 42, segments = 36;
    constexpr float start = 2.35f, sweep = 4.71f;  // from lower-left, 270 degrees clockwise
    const float temp = isnan(stats_.tempC) ? 0 : stats_.tempC;
    const float level = std::clamp((temp - 20) / 60, 0.0f, 1.0f);  // the scale runs 20-80 °C
    // Ease the needle in when the scene starts, like a real instrument powering up.
    const float shown = level * std::min(1.0f, t * 1.5f);

    for (int s = 0; s < segments; s++) {
      const float a0 = start + sweep * s / segments, a1 = start + sweep * (s + 0.8f) / segments;
      const float pos = float(s) / segments;
      const uint16_t lit = pos < 0.5f ? mix(pal::teal, pal::amber, uint8_t(pos * 2 * 255))
                                      : mix(pal::amber, pal::coral, uint8_t((pos - 0.5f) * 2 * 255));
      const uint16_t c = pos < shown ? lit : pal::dim;
      const int16_t x0 = cx + cosf(a0) * rOut, y0 = cy + sinf(a0) * rOut, x1 = cx + cosf(a1) * rOut, y1 = cy + sinf(a1) * rOut;
      const int16_t x2 = cx + cosf(a1) * rIn, y2 = cy + sinf(a1) * rIn, x3 = cx + cosf(a0) * rIn, y3 = cy + sinf(a0) * rIn;
      fb.fillTriangle(x0, y0, x1, y1, x2, y2, c);
      fb.fillTriangle(x0, y0, x2, y2, x3, y3, c);
    }

    char text[12];
    snprintf(text, sizeof(text), isnan(stats_.tempC) ? "--" : "%.1f", temp);
    centred(fb, &FreeSansBold12pt7b, text, cx, cy + 6, pal::ink);
    fb.drawCircle(cx + textWidth(fb, &FreeSansBold12pt7b, text) / 2 + 4, cy - 10, 2, pal::ink);  // degree sign
    centred(fb, nullptr, "CHIP TEMP C", cx, cy + 22, pal::muted);
    centred(fb, nullptr, "20", cx - 40, cy + 46, pal::muted);
    centred(fb, nullptr, "80", cx + 40, cy + 46, pal::muted);
  }

  // ---- Memory bars ------------------------------------------------------------------------
  void drawMemory(FrameBuffer &fb) {
    fb.setFont(&FreeSans9pt7b);
    fb.setTextColor(pal::ink);
    fb.setCursor(150, 22);
    fb.print("ESP32-S3 N16R8");

    const size_t intTotal = heap_caps_get_total_size(MALLOC_CAP_INTERNAL);
    const size_t intFree = heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
    const size_t psTotal = heap_caps_get_total_size(MALLOC_CAP_SPIRAM);
    const size_t psFree = heap_caps_get_free_size(MALLOC_CAP_SPIRAM);
    bar(fb, 150, 34, "RAM", intTotal - intFree, intTotal);
    bar(fb, 150, 58, "PSRAM", psTotal - psFree, psTotal);
  }

  void bar(FrameBuffer &fb, int x, int y, const char *label, size_t used, size_t total) {
    constexpr int w = 160, h = 8;
    const int fill = total ? int(w * double(used) / total) : 0;
    fb.setFont(nullptr);
    fb.setTextSize(1);
    fb.setTextColor(pal::muted);
    fb.setCursor(x, y);
    fb.print(label);
    char right[24];
    snprintf(right, sizeof(right), "%u / %u KB", unsigned(used / 1024), unsigned(total / 1024));
    fb.setCursor(x + w - int(strlen(right)) * 6, y);
    fb.print(right);
    fb.fillRoundRect(x, y + 10, w, h, 3, pal::dim);
    if (fill > 0) fb.fillRoundRect(x, y + 10, std::max(fill, 6), h, 3, pal::teal);
  }

  // ---- Frame time chart --------------------------------------------------------------------
  void drawFrameChart(FrameBuffer &fb) {
    constexpr int x0 = 150, y0 = 96, w = 160, h = 60;
    constexpr float maxMs = 80;
    fb.setFont(nullptr);
    fb.setTextColor(pal::muted);
    fb.setCursor(x0, y0 - 10);
    fb.printf("FRAME TIME  %.0f ms", stats_.drawMs + stats_.pushMs);
    for (float ms : {20.0f, 40.0f, 60.0f}) {
      const int y = y0 + h - int(h * ms / maxMs);
      for (int x = x0; x < x0 + w; x += 4) fb.drawPixel(x, y, pal::dim);
    }
    int prevX = -1, prevY = 0;
    for (int i = 0; i < Stats::kHistory; i++) {
      const int x = x0 + i * w / Stats::kHistory;
      const int y = y0 + h - int(h * std::min(stats_.at(i), maxMs) / maxMs);
      fb.drawFastVLine(x, y, y0 + h - y, mix(pal::night, pal::teal, 70));  // area under the line
      if (prevX >= 0) fb.drawLine(prevX, prevY, x, y, pal::teal);
      prevX = x, prevY = y;
    }
    fb.fillCircle(prevX, prevY, 2, pal::amber);  // the newest frame
    fb.setCursor(x0, y0 + h + 4);
    fb.print("last 120 frames, grid every 20 ms");
  }

  // ---- Text helpers ------------------------------------------------------------------------
  static int16_t textWidth(FrameBuffer &fb, const GFXfont *font, const char *s) {
    int16_t x1, y1;
    uint16_t w, h;
    fb.setFont(font);
    fb.setTextSize(1);
    fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
    return int16_t(w);
  }

  static void centred(FrameBuffer &fb, const GFXfont *font, const char *s, int cx, int baseline, uint16_t c) {
    const int16_t w = textWidth(fb, font, s);
    fb.setTextColor(c);
    // The built-in font draws from its top-left corner, custom fonts from their baseline.
    fb.setCursor(cx - w / 2, font ? baseline : baseline - 7);
    fb.print(s);
  }

  const Stats &stats_;
};

// Scene 3: fireworks, a particle system.
//
// A particle is just a position, a speed and a remaining life. Each frame we apply
// gravity and air drag, move it, and draw it dimmer as its life runs out.
// The trails come from never clearing the picture: each frame every pixel is darkened
// a little instead, so old positions fade out slowly.
//
// The trails need their own layer that survives between frames (the shared frame buffer
// also gets the HUD and the title banner drawn on top). It lives in PSRAM: 106 KB there is nothing.
#pragma once

#include <Arduino.h>
#include <esp_heap_caps.h>

#include <algorithm>

#include "color.h"
#include "../scene.h"

class FireworksScene : public Scene {
 public:
  const char *name() const override { return "Fireworks"; }

  void enter(FrameBuffer &fb) override {
    const size_t count = size_t(fb.width()) * fb.height();
    if (layer_ == nullptr) {
      layer_ = static_cast<uint16_t *>(heap_caps_malloc(count * sizeof(uint16_t), MALLOC_CAP_SPIRAM));
      if (layer_ == nullptr) log_e("Fireworks: no PSRAM for the trail layer");
    }
    if (layer_ != nullptr) std::fill_n(layer_, count, uint16_t(0));
    for (Particle &p : particles_) p.life = 0;
    nextLaunch_ = 0;
  }

  void render(FrameBuffer &fb, float t, float dt) override {
    const int w = fb.width(), h = fb.height();
    if (layer_ == nullptr) {
      fb.fillScreen(pal::night);
      return;
    }
    dt = std::min(dt, 0.05f);  // a slow frame should not make particles jump

    // Fade: scale each channel by 13/16. Small values reach 0, so trails fully disappear.
    for (int k = 0; k < w * h; k++) {
      const uint16_t c = layer_[k];
      if (c == 0) continue;
      const uint16_t r = ((c >> 11) * 13) >> 4, g = (((c >> 5) & 63) * 13) >> 4, b = ((c & 31) * 13) >> 4;
      layer_[k] = uint16_t((r << 11) | (g << 5) | b);
    }

    if (t >= nextLaunch_) {
      spawn(random(40, w - 40), h, random(-25, 25), -random(150, 205), 2.0f, uint8_t(random(256)), true);
      nextLaunch_ = t + random(350, 900) / 1000.0f;
    }

    for (Particle &p : particles_) {
      if (p.life <= 0) continue;
      p.vy += kGravity * dt;
      if (!p.rocket) p.vx *= 0.985f, p.vy *= 0.985f;  // air drag on sparks
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.life -= dt;

      if (p.rocket) {
        plot(w, h, p.x, p.y, rgb(255, 240, 210), 2);
        if (p.vy > -25) explode(p);  // near the top of its arc
        continue;
      }
      const float k = std::max(0.0f, p.life / p.maxLife);
      const uint16_t c = hsv(p.hue, uint8_t(255 - 120 * (1 - k) * (1 - k)), uint8_t(255 * k));
      plot(w, h, p.x, p.y, c, k > 0.55f ? 2 : 1);
    }

    std::copy_n(layer_, w * h, fb.pixels());
    fb.setFont(nullptr);
    fb.setTextSize(1);
    fb.setTextColor(pal::muted);
    fb.setCursor(8, 8);
    fb.printf("%d particles", alive());
  }

 private:
  struct Particle {
    float x, y, vx, vy, life, maxLife;
    uint8_t hue;
    bool rocket;
  };
  static constexpr int kMax = 800;
  static constexpr float kGravity = 95;  // pixels per second, per second

  void spawn(float x, float y, float vx, float vy, float life, uint8_t hue, bool rocket) {
    for (int n = 0; n < kMax; n++) {
      Particle &p = particles_[cursor_];
      cursor_ = (cursor_ + 1) % kMax;
      if (p.life > 0) continue;
      p = {x, y, vx, vy, life, life, hue, rocket};
      return;
    }
  }

  void explode(Particle &rocket) {
    rocket.life = 0;
    const int sparks = random(70, 120);
    for (int s = 0; s < sparks; s++) {
      const float angle = random(0, 6283) / 1000.0f, speed = random(25, 115);
      const uint8_t hue = rocket.hue + random(-12, 12);
      spawn(rocket.x, rocket.y, cosf(angle) * speed, sinf(angle) * speed, random(110, 210) / 100.0f, hue, false);
    }
  }

  void plot(int w, int h, float fx, float fy, uint16_t c, int size) {
    const int x = int(fx), y = int(fy);
    for (int dy = 0; dy < size; dy++)
      for (int dx = 0; dx < size; dx++)
        if (x + dx >= 0 && x + dx < w && y + dy >= 0 && y + dy < h) layer_[(y + dy) * w + x + dx] = c;
  }

  int alive() const {
    int n = 0;
    for (const Particle &p : particles_) n += p.life > 0;
    return n;
  }

  Particle particles_[kMax] = {};
  int cursor_ = 0;
  float nextLaunch_ = 0;
  uint16_t *layer_ = nullptr;
};

// Scene 2: plasma, a classic 1990s demo effect.
//
// Each pixel's colour is the sum of four sine waves running in different directions,
// one of them in circles around a wandering centre. Summing waves gives the liquid look.
// Sines are slow to compute, so we pre-compute 256 of them once (a lookup table)
// and also a 256-colour palette. Per pixel it is then only a few table lookups.
#pragma once

#include <math.h>

#include "color.h"
#include "../scene.h"

class PlasmaScene : public Scene {
 public:
  PlasmaScene() {
    for (int i = 0; i < 256; i++) {
      sine_[i] = uint8_t(128 + 127 * sinf(i * 6.2831853f / 256));
      // A cosine palette: deep indigo -> magenta -> orange -> pale gold, and back.
      const float f = i / 256.0f;
      auto channel = [f](float offset) { return uint8_t(255 * (0.5f + 0.5f * cosf(6.2831853f * (f + offset)))); };
      palette_[i] = rgb(channel(0.0f), uint8_t(channel(0.18f) * 0.75f), channel(0.42f));
    }
  }

  const char *name() const override { return "Plasma"; }

  void render(FrameBuffer &fb, float t, float) override {
    const int w = fb.width(), h = fb.height();
    const uint8_t t1 = uint8_t(t * 47), t2 = uint8_t(t * 29), shift = uint8_t(t * 21);
    const int cx = int(w / 2 + 110 * sinf(t * 0.63f)), cy = int(h / 2 + 55 * cosf(t * 0.81f));

    uint16_t *p = fb.pixels();
    for (int y = 0; y < h; y++) {
      const uint8_t row = sine_[uint8_t(y * 3 - t2)];
      const int dy = y - cy;
      for (int x = 0; x < w; x++) {
        const int dx = x - cx;
        const int v = sine_[uint8_t(x * 2 + t1)] + row + sine_[uint8_t(x + y + t2)] +
                      sine_[uint8_t(((dx * dx + dy * dy) >> 7) - t1)];
        *p++ = palette_[uint8_t((v >> 2) + shift)];
      }
    }

    fb.setFont(nullptr);
    fb.setTextSize(1);
    fb.setTextColor(pal::ink);
    fb.setCursor(8, 8);
    fb.printf("%d pixels computed every frame", w * h);
  }

 private:
  uint8_t sine_[256];
  uint16_t palette_[256];
};

// Scene 1: a shaded 3D torus (a ring), built from flat four-sided faces.
//
// Every frame:
//   1. rotate each corner point in 3D
//   2. project it onto the 2D screen (things further away get closer to the centre)
//   3. throw away faces that point away from us (backface culling)
//   4. light each face by how directly it faces the light
//   5. sort faces far-to-near and paint them in that order (painter's algorithm)
#pragma once

#include <math.h>

#include <algorithm>

#include "color.h"
#include "../scene.h"

class TorusScene : public Scene {
 public:
  TorusScene() {
    // Corner points on the ring surface, and the outward direction at each face centre.
    for (int i = 0; i < kU; i++) {
      for (int j = 0; j < kV; j++) {
        const float u = i * kTau / kU, v = j * kTau / kV;
        points_[i * kV + j] = {(kR + kr * cosf(v)) * cosf(u), (kR + kr * cosf(v)) * sinf(u), kr * sinf(v)};
        const float uc = (i + 0.5f) * kTau / kU, vc = (j + 0.5f) * kTau / kV;
        normals_[i * kV + j] = {cosf(vc) * cosf(uc), cosf(vc) * sinf(uc), sinf(vc)};
      }
    }
    // A night-sky gradient behind the ring, one colour per row.
    for (int y = 0; y < kH; y++) sky_[y] = mix(rgb(16, 22, 40), rgb(4, 6, 12), y * 255 / kH);
  }

  const char *name() const override { return "3D torus"; }

  void render(FrameBuffer &fb, float t, float) override {
    for (int y = 0; y < kH; y++) fb.drawFastHLine(0, y, kW, sky_[y]);

    // Rotation angles. Two different speeds make the motion feel organic.
    const float ca = cosf(t * 0.9f), sa = sinf(t * 0.9f);
    const float cb = cosf(t * 0.55f), sb = sinf(t * 0.55f);
    auto rotate = [&](const Vec &p) {
      const float y1 = p.y * ca - p.z * sa, z1 = p.y * sa + p.z * ca;
      return Vec{p.x * cb + z1 * sb, y1, -p.x * sb + z1 * cb};
    };

    // 1 + 2: rotate and project every corner point.
    for (int k = 0; k < kU * kV; k++) {
      const Vec r = rotate(points_[k]);
      const float z = r.z + kCamera;
      sx_[k] = int16_t(kW / 2 + r.x * kFocal / z);
      sy_[k] = int16_t(kH / 2 + r.y * kFocal / z);
      sz_[k] = z;
    }

    // 3 + 4: keep faces that point at us, and light them.
    visible_ = 0;
    for (int i = 0; i < kU; i++) {
      for (int j = 0; j < kV; j++) {
        const int a = i * kV + j, b = ((i + 1) % kU) * kV + j;
        const int c = ((i + 1) % kU) * kV + (j + 1) % kV, d = i * kV + (j + 1) % kV;
        const Vec n = rotate(normals_[a]);
        const Vec centre = rotate(points_[a]);
        // The face points at us when its normal and the line from the camera to it disagree.
        if (n.x * centre.x + n.y * centre.y + n.z * (centre.z + kCamera) >= 0) continue;

        const float diffuse = std::max(0.0f, n.x * kLight.x + n.y * kLight.y + n.z * kLight.z);
        const uint8_t level = uint8_t(40 + 215 * diffuse);
        const bool stripe = ((i / 2) + j) % 2 == 0;
        Face &f = faces_[visible_++];
        f.depth = sz_[a] + sz_[b] + sz_[c] + sz_[d];
        f.color = mix(pal::night, stripe ? pal::amber : pal::teal, level);
        f.corners[0] = a, f.corners[1] = b, f.corners[2] = c, f.corners[3] = d;
      }
    }

    // 5: paint far faces first so near ones cover them.
    std::sort(faces_, faces_ + visible_, [](const Face &l, const Face &r) { return l.depth > r.depth; });
    for (int k = 0; k < visible_; k++) {
      const int16_t *q = faces_[k].corners;
      fb.fillTriangle(sx_[q[0]], sy_[q[0]], sx_[q[1]], sy_[q[1]], sx_[q[2]], sy_[q[2]], faces_[k].color);
      fb.fillTriangle(sx_[q[0]], sy_[q[0]], sx_[q[2]], sy_[q[2]], sx_[q[3]], sy_[q[3]], faces_[k].color);
    }

    fb.setFont(nullptr);
    fb.setTextSize(1);
    fb.setTextColor(pal::muted);
    fb.setCursor(8, 8);
    fb.printf("%d faces, %d drawn", kU * kV, visible_);
  }

 private:
  struct Vec {
    float x, y, z;
  };
  struct Face {
    float depth;
    uint16_t color;
    int16_t corners[4];
  };

  static constexpr int kW = 320, kH = 170;
  static constexpr int kU = 24, kV = 10;              // segments around the ring and around the tube
  static constexpr float kR = 1.0f, kr = 0.42f;        // ring radius, tube radius
  static constexpr float kCamera = 3.4f, kFocal = 175;  // camera distance and lens "zoom"
  static constexpr float kTau = 6.2831853f;
  static constexpr Vec kLight = {-0.45f, -0.6f, -0.66f};  // towards the light: up, left, in front

  Vec points_[kU * kV];
  Vec normals_[kU * kV];
  int16_t sx_[kU * kV], sy_[kU * kV];
  float sz_[kU * kV];
  Face faces_[kU * kV];
  int visible_ = 0;
  uint16_t sky_[kH];
};

// Frame timing and chip readings, shared by the HUD, the serial log and the dashboard scene.
#pragma once

#include <math.h>

struct Stats {
  static constexpr int kHistory = 120;  // frames kept for the dashboard chart

  float fps = 0;
  float drawMs = 0;  // time spent drawing the picture in memory
  float pushMs = 0;  // time spent sending it over SPI
  float tempC = NAN;
  float frameMs[kHistory] = {};
  int head = 0;

  void add(float draw, float push, float dtSeconds) {
    drawMs = drawMs * 0.9f + draw * 0.1f;  // smoothed so the numbers don't jitter
    pushMs = pushMs * 0.9f + push * 0.1f;
    if (dtSeconds > 0) fps = fps * 0.9f + (1.0f / dtSeconds) * 0.1f;
    frameMs[head] = draw + push;
    head = (head + 1) % kHistory;
  }

  // i = 0 is the oldest sample, kHistory - 1 the newest.
  float at(int i) const { return frameMs[(head + i) % kHistory]; }
};

// Every scene follows the same small contract, so main.cpp can switch between them
// without knowing how any of them draws.
#pragma once

#include "frame_buffer.h"

class Scene {
 public:
  virtual ~Scene() = default;
  virtual const char *name() const = 0;
  // Called each time the scene comes on screen.
  virtual void enter(FrameBuffer &) {}
  // t = seconds since the scene came on screen, dt = seconds since the last frame.
  virtual void render(FrameBuffer &fb, float t, float dt) = 0;
};

// The BOOT button on the board, used as a normal input once the program is running.
// It connects GPIO 0 to GND when pressed, so we enable the internal pull-up and read LOW = pressed.
//
// Mechanical buttons "bounce": one press flickers on/off for a few milliseconds.
// We only trust a new state once it has been stable for kDebounceMs.
#pragma once

#include <Arduino.h>

class BootButton {
 public:
  enum class Event { None, Click, LongPress };

  explicit BootButton(uint8_t pin) : pin_(pin) {}

  void begin() { pinMode(pin_, INPUT_PULLUP); }

  Event poll() {
    const bool raw = digitalRead(pin_) == LOW;
    const uint32_t now = millis();
    if (raw != lastRaw_) {
      lastRaw_ = raw;
      changedAt_ = now;
    }
    if (now - changedAt_ < kDebounceMs || raw == pressed_) return Event::None;

    pressed_ = raw;
    if (pressed_) {
      pressedAt_ = now;
      return Event::None;
    }
    return now - pressedAt_ >= kLongPressMs ? Event::LongPress : Event::Click;
  }

 private:
  static constexpr uint32_t kDebounceMs = 30;
  static constexpr uint32_t kLongPressMs = 600;

  uint8_t pin_;
  bool lastRaw_ = false;
  bool pressed_ = false;
  uint32_t changedAt_ = 0;
  uint32_t pressedAt_ = 0;
};

// Variation 2: an external push button on GPIO 5, plus the BOOT button. Both do the same:
//   click = next scene · double-click = previous scene · long press (0.6 s) = auto-cycle on/off
//
// Wiring: GPIO 5 -> one leg of the button, the diagonally opposite leg -> GND.
// Both buttons use interrupts to catch every contact bounce (see button.h).
#include "button.h"
#include "../controls.h"
#include "pins.h"

namespace {

Button external(PIN_BUTTON, "button");
Button boot(PIN_BOOT_BTN, "BOOT");

Action toAction(Button &b) {
  switch (b.poll()) {
    case Button::Event::Click:
      log_i("%s: click (%lu bounces filtered)", b.name(), static_cast<unsigned long>(b.lastBounces()));
      return Action::NextScene;
    case Button::Event::DoubleClick:
      log_i("%s: double-click", b.name());
      return Action::PreviousScene;
    case Button::Event::LongPress:
      log_i("%s: long press", b.name());
      return Action::ToggleAutoCycle;
    case Button::Event::None:
      break;
  }
  return Action::None;
}

}  // namespace

namespace controls {

void begin() {
  external.begin();
  boot.begin();
  log_i("Controls: button on GPIO %d and BOOT on GPIO %d (variation 2)", PIN_BUTTON, PIN_BOOT_BTN);
}

Action poll() {
  // Poll both every frame so neither misses a gesture; report the external button first.
  const Action a = toAction(external);
  const Action b = toAction(boot);
  return a != Action::None ? a : b;
}

bool anyDown() { return external.isDown() || boot.isDown(); }
bool showsPressDot() { return true; }
const char *help() { return "Button (GPIO 5) or BOOT: click = next, double-click = previous, long press = auto-cycle"; }

}  // namespace controls

// Colour helpers for the 16-bit RGB565 format the ST7789 speaks: 5 bits red, 6 green, 5 blue.
#pragma once

#include <stdint.h>

constexpr uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return uint16_t(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// Hue 0-255 around the colour wheel, saturation and value 0-255.
inline uint16_t hsv(uint8_t h, uint8_t s, uint8_t v) {
  const uint8_t region = h / 43;
  const uint8_t rem = (h - region * 43) * 6;
  const uint8_t p = (v * (255 - s)) >> 8;
  const uint8_t q = (v * (255 - ((s * rem) >> 8))) >> 8;
  const uint8_t t = (v * (255 - ((s * (255 - rem)) >> 8))) >> 8;
  switch (region) {
    case 0: return rgb(v, t, p);
    case 1: return rgb(q, v, p);
    case 2: return rgb(p, v, t);
    case 3: return rgb(p, q, v);
    case 4: return rgb(t, p, v);
    default: return rgb(v, p, q);
  }
}

// Mix two colours: k = 0 gives a, k = 255 gives b.
inline uint16_t mix(uint16_t a, uint16_t b, uint8_t k) {
  const int ar = a >> 11, ag = (a >> 5) & 63, ab = a & 31;
  const int br = b >> 11, bg = (b >> 5) & 63, bb = b & 31;
  return uint16_t(((ar + ((br - ar) * k >> 8)) << 11) | ((ag + ((bg - ag) * k >> 8)) << 5) | (ab + ((bb - ab) * k >> 8)));
}

